func (os PoolSlice) Household(mods ...bob.Mod[*dialect.SelectQuery]) HouseholdsQuery {
	pkHouseholdID := make(pgtypes.Array[uuid.UUID], 0, len(os))

	// the array is only a filter (semi-join), so duplicate keys can be
	// dropped before they are sent over the wire
	seenHouseholdID := make(map[uuid.UUID]struct{}, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		if _, ok := seenHouseholdID[o.HouseholdID]; ok {
			continue
		}
		seenHouseholdID[o.HouseholdID] = struct{}{}
		pkHouseholdID = append(pkHouseholdID, o.HouseholdID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkHouseholdID), "uuid[]"))

	return Households.Query(append(mods,
		sm.Where(Households.Columns.ID.EQ(PKArgExpr)),
	)...)
}

