type poolWhere[Q psql.Filterable] struct {
	cols               poolColumns
	ID                 psql.WhereMod[Q, uuid.UUID]
	HouseholdID        psql.WhereMod[Q, uuid.UUID]
	Name               psql.WhereMod[Q, string]
	Kind               psql.WhereMod[Q, string]
	CreatedAt          psql.WhereMod[Q, time.Time]
	FundingRuleVersion psql.WhereMod[Q, int32]
	R                  poolWhereR[Q]
}

func (poolWhere[Q]) AliasedAs(alias string) poolWhere[Q] {
	return buildPoolWhere[Q](buildPoolColumns(alias))
}

func buildPoolWhere[Q psql.Filterable](cols poolColumns) poolWhere[Q] {
	return poolWhere[Q]{
		cols:               cols,
		ID:                 psql.Where[Q, uuid.UUID](cols.ID.Expression),
		HouseholdID:        psql.Where[Q, uuid.UUID](cols.HouseholdID.Expression),
		Name:               psql.Where[Q, string](cols.Name.Expression),
		Kind:               psql.Where[Q, string](cols.Kind.Expression),
		CreatedAt:          psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		FundingRuleVersion: psql.Where[Q, int32](cols.FundingRuleVersion.Expression),
		R:                  poolWhereR[Q]{cols: cols},
	}
}

// poolWhereR holds the relationship-based filters of
// poolWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type poolWhereR[Q psql.Filterable] struct {
	cols poolColumns
}

// HasAccounts filters parents that have a matching Accounts using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Accounts).
func (w poolWhereR[Q]) HasAccounts(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Accounts.NameExpr()),
		sm.Where(Accounts.Columns.HouseholdID.EQ(w.cols.HouseholdID)),
		sm.Where(Accounts.Columns.PoolID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

