// NULL-tolerant scan buffer for poolScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type poolPreloadBuf struct {
	ID                 sql.Null[uuid.UUID]
	HouseholdID        sql.Null[uuid.UUID]
	Name               sql.Null[string]
	Kind               sql.Null[string]
	CreatedAt          sql.Null[time.Time]
	FundingRuleVersion sql.Null[int32]
}

// poolScanMapperNullable maps the preloaded pool
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func poolScanMapperNullable(prefix string) scan.Mapper[*Pool] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Pool, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *poolPreloadBuf) any
		}
		targets := make([]target, 0, 6)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *poolPreloadBuf) any { return &b.ID }})
			case "household_id":
				targets = append(targets, target{i, func(b *poolPreloadBuf) any { return &b.HouseholdID }})
			case "name":
				targets = append(targets, target{i, func(b *poolPreloadBuf) any { return &b.Name }})
			case "kind":
				targets = append(targets, target{i, func(b *poolPreloadBuf) any { return &b.Kind }})
			case "created_at":
				targets = append(targets, target{i, func(b *poolPreloadBuf) any { return &b.CreatedAt }})
			case "funding_rule_version":
				targets = append(targets, target{i, func(b *poolPreloadBuf) any { return &b.FundingRuleVersion }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(poolPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Pool, error) {
				buf := link.(*poolPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.Valid) &&
					!(buf.HouseholdID.Valid) &&
					!(buf.Name.Valid) &&
					!(buf.Kind.Valid) &&
					!(buf.CreatedAt.Valid) &&
					!(buf.FundingRuleVersion.Valid) {
					return nil, nil
				}

				o := new(Pool)
				if buf.ID.Valid {
					o.ID = buf.ID.V
				}
				if buf.HouseholdID.Valid {
					o.HouseholdID = buf.HouseholdID.V
				}
				if buf.Name.Valid {
					o.Name = buf.Name.V
				}
				if buf.Kind.Valid {
					o.Kind = buf.Kind.V
				}
				if buf.CreatedAt.Valid {
					o.CreatedAt = buf.CreatedAt.V
				}
				if buf.FundingRuleVersion.Valid {
					o.FundingRuleVersion = buf.FundingRuleVersion.V
				}
				return o, nil
			}
	}
}

func (o *Pool) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Accounts":
		rels, ok := retrieved.(AccountSlice)
		if !ok {
			return fmt.Errorf("pool cannot load %T as %q", retrieved, name)
		}

		o.R.Accounts = rels
		o.R.Loaded.Accounts = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Pool = o
				rel.R.Loaded.Pool = true
			}
		}
		return nil
	case "AllocationDefaults":
		rels, ok := retrieved.(AllocationDefaultSlice)
		if !ok {
			return fmt.Errorf("pool cannot load %T as %q", retrieved, name)
		}

		o.R.AllocationDefaults = rels
		o.R.Loaded.AllocationDefaults = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Pool = o
				rel.R.Loaded.Pool = true
			}
		}
		return nil
	case "AllocationRuleWeights":
		rels, ok := retrieved.(AllocationRuleWeightSlice)
		if !ok {
			return fmt.Errorf("pool cannot load %T as %q", retrieved, name)
		}

		o.R.AllocationRuleWeights = rels
		o.R.Loaded.AllocationRuleWeights = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Pool = o
				rel.R.Loaded.Pool = true
			}
		}
		return nil
	case "FundingObligations":
		rels, ok := retrieved.(FundingObligationSlice)
		if !ok {
			return fmt.Errorf("pool cannot load %T as %q", retrieved, name)
		}

		o.R.FundingObligations = rels
		o.R.Loaded.FundingObligations = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Pool = o
				rel.R.Loaded.Pool = true
			}
		}
		return nil
	case "FundingSchedules":
		rels, ok := retrieved.(FundingScheduleSlice)
		if !ok {
			return fmt.Errorf("pool cannot load %T as %q", retrieved, name)
		}

		o.R.FundingSchedules = rels
		o.R.Loaded.FundingSchedules = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Pool = o
				rel.R.Loaded.Pool = true
			}
		}
		return nil
	case "ItemAllocations":
		rels, ok := retrieved.(ItemAllocationSlice)
		if !ok {
			return fmt.Errorf("pool cannot load %T as %q", retrieved, name)
		}

		o.R.ItemAllocations = rels
		o.R.Loaded.ItemAllocations = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Pool = o
				rel.R.Loaded.Pool = true
			}
		}
		return nil
	case "LedgerEntries":
		rels, ok := retrieved.(LedgerEntrySlice)
		if !ok {
			return fmt.Errorf("pool cannot load %T as %q", retrieved, name)
		}

		o.R.LedgerEntries = rels
		o.R.Loaded.LedgerEntries = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Pool = o
				rel.R.Loaded.Pool = true
			}
		}
		return nil
	case "PoolFundingRules":
		rels, ok := retrieved.(PoolFundingRuleSlice)
		if !ok {
			return fmt.Errorf("pool cannot load %T as %q", retrieved, name)
		}

		o.R.PoolFundingRules = rels
		o.R.Loaded.PoolFundingRules = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Pool = o
				rel.R.Loaded.Pool = true
			}
		}
		return nil
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("pool cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.Pools = PoolSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("pool has no relationship %q", name)
	}
}

type poolPreloader struct {
	Household func(...psql.PreloadOption) psql.Preloader
}

func buildPoolPreloader() poolPreloader {
	return poolPreloader{
		Household: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Household, HouseholdSlice](psql.PreloadRel{
				Name: "Household",
				Sides: []psql.PreloadSide{
					{
						From:        Pools,
						To:          Households,
						FromColumns: []string{"household_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Households.Columns.Names(), householdScanMapperNullable, opts...)
		},
	}
}

