// LoadAccounts loads the pool's Accounts into the .R struct
func (o *Pool) LoadAccounts(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Accounts = nil
	o.R.Loaded.Accounts = false

	related, err := o.Accounts(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Pool = o
		rel.R.Loaded.Pool = true
	}

	o.R.Accounts = related
	o.R.Loaded.Accounts = true
	return nil
}

// LoadAccounts loads the pool's Accounts into the .R struct
func (os PoolSlice) LoadAccounts(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	accounts, err := os.Accounts(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Accounts = nil
		o.R.Loaded.Accounts = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range accounts {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !rel.PoolID.Valid {
				continue
			}
			if !(rel.PoolID.Valid && o.ID == rel.PoolID.V) {
				continue
			}

			rel.R.Pool = o
			rel.R.Loaded.Pool = true

			o.R.Accounts = append(o.R.Accounts, rel)
		}
	}

	return nil
}

