type poolCountThenLoader[Q orm.Loadable] struct {
	Accounts              func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	AllocationDefaults    func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	AllocationRuleWeights func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	FundingObligations    func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	FundingSchedules      func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	ItemAllocations       func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	LedgerEntries         func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	PoolFundingRules      func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildPoolCountThenLoader[Q orm.Loadable]() poolCountThenLoader[Q] {
	type AccountsCountInterface interface {
		LoadCountAccounts(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type AllocationDefaultsCountInterface interface {
		LoadCountAllocationDefaults(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type AllocationRuleWeightsCountInterface interface {
		LoadCountAllocationRuleWeights(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type FundingObligationsCountInterface interface {
		LoadCountFundingObligations(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type FundingSchedulesCountInterface interface {
		LoadCountFundingSchedules(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type ItemAllocationsCountInterface interface {
		LoadCountItemAllocations(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type LedgerEntriesCountInterface interface {
		LoadCountLedgerEntries(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type PoolFundingRulesCountInterface interface {
		LoadCountPoolFundingRules(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return poolCountThenLoader[Q]{
		Accounts: countThenLoadBuilder[Q](
			"Accounts",
			func(ctx context.Context, exec bob.Executor, retrieved AccountsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountAccounts(ctx, exec, mods...)
			},
		),
		AllocationDefaults: countThenLoadBuilder[Q](
			"AllocationDefaults",
			func(ctx context.Context, exec bob.Executor, retrieved AllocationDefaultsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountAllocationDefaults(ctx, exec, mods...)
			},
		),
		AllocationRuleWeights: countThenLoadBuilder[Q](
			"AllocationRuleWeights",
			func(ctx context.Context, exec bob.Executor, retrieved AllocationRuleWeightsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountAllocationRuleWeights(ctx, exec, mods...)
			},
		),
		FundingObligations: countThenLoadBuilder[Q](
			"FundingObligations",
			func(ctx context.Context, exec bob.Executor, retrieved FundingObligationsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountFundingObligations(ctx, exec, mods...)
			},
		),
		FundingSchedules: countThenLoadBuilder[Q](
			"FundingSchedules",
			func(ctx context.Context, exec bob.Executor, retrieved FundingSchedulesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountFundingSchedules(ctx, exec, mods...)
			},
		),
		ItemAllocations: countThenLoadBuilder[Q](
			"ItemAllocations",
			func(ctx context.Context, exec bob.Executor, retrieved ItemAllocationsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountItemAllocations(ctx, exec, mods...)
			},
		),
		LedgerEntries: countThenLoadBuilder[Q](
			"LedgerEntries",
			func(ctx context.Context, exec bob.Executor, retrieved LedgerEntriesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountLedgerEntries(ctx, exec, mods...)
			},
		),
		PoolFundingRules: countThenLoadBuilder[Q](
			"PoolFundingRules",
			func(ctx context.Context, exec bob.Executor, retrieved PoolFundingRulesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountPoolFundingRules(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountAccounts loads the count of Accounts into the C struct
func (o *Pool) LoadCountAccounts(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.Accounts(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.Accounts = &count
	return nil
}

// LoadCountAccounts loads the count of Accounts for a slice in a single batch query
func (os PoolSlice) LoadCountAccounts(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkHouseholdID := make(pgtypes.Array[uuid.UUID], 0, len(os))
	pkID := make(pgtypes.Array[uuid.UUID], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkHouseholdID = append(pkHouseholdID, o.HouseholdID)
		pkID = append(pkID, o.ID)
	}

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		HouseholdID uuid.UUID

		ID    uuid.UUID
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			Accounts.Columns.HouseholdID.As("household_id"),
			Accounts.Columns.PoolID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(Accounts.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.InnerJoin(psql.Select(
			sm.Distinct(),
			sm.Columns(
				psql.Quote("bob_rel_keys_src", "HouseholdID"),
				psql.Quote("bob_rel_keys_src", "PoolID"),
			),
			sm.From(psql.F("unnest",
				psql.Cast(psql.Arg(pkHouseholdID), "uuid[]"),
				psql.Cast(psql.Arg(pkID), "uuid[]"),
			)).As("bob_rel_keys_src", "HouseholdID", "PoolID"),
		)).As("bob_rel_keys").On(
			Accounts.Columns.HouseholdID.EQ(psql.Quote("bob_rel_keys", "HouseholdID")),
			Accounts.Columns.PoolID.EQ(psql.Quote("bob_rel_keys", "PoolID")),
		),
		// GROUP BY fk columns
		sm.GroupBy(Accounts.Columns.HouseholdID),
		sm.GroupBy(Accounts.Columns.PoolID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Composite FK: use a key struct
	type countKey struct {
		HouseholdID uuid.UUID

		ID uuid.UUID
	}
	countMap := make(map[countKey]int64, len(results))
	for _, r := range results {
		countMap[countKey{
			HouseholdID: r.HouseholdID,

			ID: r.ID,
		}] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[countKey{
			HouseholdID: o.HouseholdID,

			ID: o.ID,
		}]
		o.C.Accounts = &count
	}

	return nil
}

